import * as React from "react";

import type { CipherLinkProps } from "../lib/link";
import { cn } from "../lib/utils";
import { Card, CardContent, CardLink } from "./card";
import { Icon, type IconSource } from "./icon";
import { Media } from "./item";
import { Skeleton } from "./skeleton";
import { StatusText } from "./text";

import styles from "./stat-card.module.css";

const trendIcon = {
  up: "arrow-up",
  down: "arrow-down",
  flat: "minus"
} as const;
const trendTone = { up: "ok", down: "bad", flat: "neutral" } as const;
const chartHeight = { sm: 92, md: 168 } as const;

/** The pixel height of the StatCard chart band the chart sits in, for chart components that fill it. */
export const StatCardChartHeight = React.createContext<number>(chartHeight.sm);

export type StatCardProps = Omit<
  React.ComponentProps<typeof Card>,
  "title" | "badges" | "description" | "hint" | "action" | "children"
> & {
  label: React.ReactNode;
  value: React.ReactNode;
  icon?: IconSource;
  /** Tone of the icon, for a metric that needs attention. */
  tone?: "ok" | "warn" | "bad" | "info";
  /** The change since the last period, such as "+12%". Its text carries the direction; the arrow is decoration. */
  delta?: React.ReactNode;
  trend?: "up" | "down" | "flat";
  /** Defaults to ok for up, bad for down and neutral for flat; set it for a metric where up is bad. */
  deltaTone?: "ok" | "bad" | "neutral";
  /** A short line under the value: what the number counts, the comparison period, or a link. */
  note?: React.ReactNode;
  /** Makes the whole card a link, named by the label. */
  link?: CipherLinkProps["link"];
  loading?: boolean;
  /** Replaces the value with this message when the metric failed to load. */
  error?: React.ReactNode;
  /** A control under the note, such as the setup button of a metric that isn't set up yet. */
  action?: React.ReactNode;
  /** A chart after the value, usually a StatCardChart. Hidden while loading or failed. */
  chart?: React.ReactNode;
  /** "bleed" runs the chart to the card's left, right and bottom edges; "inset" keeps it inside the padding. */
  chartPlacement?: "inset" | "bleed";
  /** The chart band's height: sm is 92px, md is 168px. */
  chartSize?: keyof typeof chartHeight;
};

export function StatCard({
  label,
  value,
  icon,
  tone,
  delta,
  trend = "flat",
  deltaTone,
  note,
  link,
  loading = false,
  error,
  action,
  chart,
  chartPlacement = "inset",
  chartSize = "sm",
  footer,
  footerPlacement,
  variant = "framed",
  className,
  ...props
}: StatCardProps) {
  const id = React.useId();
  const labelId = `${id}-label`;
  const valueId = `${id}-value`;
  const failed = error !== undefined && error !== null && error !== false;
  const body = (
    <>
      <div className={styles.head}>
        <span id={labelId} className={styles.label}>
          {link ? (
            <CardLink link={link} aria-describedby={valueId}>
              {label}
            </CardLink>
          ) : (
            label
          )}
        </span>
        {icon && <Media icon={icon} size="sm" tone={tone} aria-hidden />}
      </div>
      {loading ? (
        <Skeleton className={styles.valueSkeleton} />
      ) : failed ? (
        <StatusText tone="bad" icon="alert" className={styles.error}>
          {error}
        </StatusText>
      ) : (
        <div id={valueId} data-slot="stat-card-value" className={styles.value}>
          {value}
        </div>
      )}
      {!loading && !failed && (delta !== undefined || note !== undefined) && (
        <div className={styles.foot}>
          {delta !== undefined && (
            <span
              data-slot="stat-card-delta"
              data-tone={deltaTone ?? trendTone[trend]}
              className={styles.delta}
            >
              <Icon name={trendIcon[trend]} aria-hidden />
              {delta}
            </span>
          )}
          {note !== undefined && <span className={styles.note}>{note}</span>}
        </div>
      )}
      {!loading && !failed && action !== undefined && <div className={styles.action}>{action}</div>}
      {!loading && !failed && chart !== undefined && (
        <div
          data-slot="stat-card-chart"
          data-placement={chartPlacement}
          className={styles.chart}
          style={{ height: chartHeight[chartSize] }}
        >
          <StatCardChartHeight value={chartHeight[chartSize]}>{chart}</StatCardChartHeight>
        </div>
      )}
    </>
  );
  return (
    <Card
      data-slot="stat-card"
      role="group"
      aria-labelledby={labelId}
      aria-busy={loading || undefined}
      variant={variant}
      footer={footer}
      footerPlacement={footerPlacement}
      className={cn(styles.statCard, className)}
      {...props}
    >
      {footer === undefined ? (
        <CardContent className={styles.body}>{body}</CardContent>
      ) : (
        <div className={styles.body}>{body}</div>
      )}
    </Card>
  );
}

.body {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
}
.statCard [data-slot="card-content"]:has(> .body) {
  display: flex;
  flex-direction: column;
}
[data-slot="card-content"] > .body {
  flex-grow: 1;
}
.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-8);
  min-width: 0;
}
.label {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.value {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--cipher-ink);
  font-family: var(--cipher-type-display-font-family);
  font-size: var(--cipher-type-display-font-size);
  line-height: var(--cipher-type-display-line-height);
  font-weight: var(--cipher-type-display-font-weight);
  letter-spacing: var(--cipher-type-display-letter-spacing);
  font-variant-numeric: tabular-nums;
}
.valueSkeleton {
  width: var(--cipher-space-48);
  height: var(--cipher-type-display-line-height);
}
.error {
  min-height: var(--cipher-type-display-line-height);
}
.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-4) var(--cipher-space-8);
  min-width: 0;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.delta {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-2);
  color: var(--cipher-text2);
  font-weight: var(--cipher-type-label-font-weight);
  font-variant-numeric: tabular-nums;
}
.delta > svg {
  width: var(--cipher-size-glyph);
  height: var(--cipher-size-glyph);
  stroke-width: var(--cipher-stroke-icon);
}
.delta[data-tone="ok"] {
  color: var(--cipher-ok);
}
.delta[data-tone="bad"] {
  color: var(--cipher-bad);
}
.note {
  min-width: 0;
  color: var(--cipher-muted);
}
.action {
  margin-top: var(--cipher-space-12);
}
.chart {
  flex: none;
  margin-top: auto;
  overflow: clip;
}
.chart[data-placement="bleed"] {
  margin-inline: calc(-1 * (var(--cipher-card-body-inset) + var(--cipher-card-lead)))
    calc(-1 * var(--cipher-card-body-inset));
  margin-bottom: calc(-1 * var(--cipher-card-body-inset));
}
.chart > [data-slot="chart"] {
  width: 100%;
}
